package it.cavallium.rockserver.core.server;

import com.google.protobuf.*;
import io.grpc.*;
import io.grpc.stub.StreamObserver;
import it.cavallium.rockserver.core.client.RemoteMutationWire;
import it.cavallium.rockserver.core.common.RequestContext;
import it.cavallium.rockserver.core.common.RequestType;
import it.cavallium.rockserver.core.common.KVBatch;
import it.cavallium.rockserver.core.common.api.proto.*;
import it.cavallium.rockserver.core.common.cdc.DistributedCdcWire;
import it.cavallium.rockserver.core.common.distributed.*;
import it.cavallium.rockserver.core.common.export.ExportWire;
import java.util.concurrent.*;
import java.util.function.*;

/** RPC cancellation detaches observation; backend futures retain durable work ownership. */
public final class RemoteMutationGrpcService extends RemoteMutationServiceGrpc.RemoteMutationServiceImplBase {
    private final RemoteMutationAsyncAPI backend;
    public RemoteMutationGrpcService(RemoteMutationAsyncAPI backend){this.backend=backend;}
    public ServerServiceDefinition bindBoundedService(){
        var generated=bindService();var descriptor=ServiceDescriptor.newBuilder(generated.getServiceDescriptor().getName()).setSchemaDescriptor(generated.getServiceDescriptor().getSchemaDescriptor());var methods=new java.util.ArrayList<ServerMethodDefinition<?,?>>();for(var method:generated.getMethods()){var bounded=bounded(method);methods.add(bounded);descriptor.addMethod(bounded.getMethodDescriptor());}var builder=ServerServiceDefinition.builder(descriptor.build());methods.forEach(method->add(builder,method));return builder.build();
    }
    private static <Q,R> void add(ServerServiceDefinition.Builder builder,ServerMethodDefinition<Q,R> method){builder.addMethod(method);}
    private static <Q,R> ServerMethodDefinition<Q,R> bounded(ServerMethodDefinition<Q,R> method){
        var descriptor=method.getMethodDescriptor();var delegate=descriptor.getRequestMarshaller();var bounded=new MethodDescriptor.Marshaller<Q>(){public java.io.InputStream stream(Q value){return delegate.stream(value);}public Q parse(java.io.InputStream input){final byte[] bytes;try{bytes=input.readNBytes(RemoteMutationWire.MAX_FRAME_BYTES+1);}catch(java.io.IOException failure){throw Status.INTERNAL.withCause(failure).asRuntimeException();}if(bytes.length>RemoteMutationWire.MAX_FRAME_BYTES)throw Status.RESOURCE_EXHAUSTED.withDescription("Mutation request exceeds byte bound").asRuntimeException();return delegate.parse(new java.io.ByteArrayInputStream(bytes));}};return ServerMethodDefinition.create(descriptor.toBuilder(bounded,descriptor.getResponseMarshaller()).build(),method.getServerCallHandler());
    }
    private <T,R extends MessageLite> void invoke(MessageLite request,boolean hasContext,it.cavallium.rockserver.core.common.api.proto.RequestContext wire,StreamObserver<R> observer,Function<RequestContext,CompletableFuture<T>> call,Function<T,R> mapper){
        var grpc=Context.current();try{
            RemoteMutationWire.bounded(request);if(!hasContext)throw new IllegalArgumentException("Missing mutation request context");var context=DistributedCdcWire.context(wire);if(grpc.isCancelled())throw Status.CANCELLED.asRuntimeException();var deadline=grpc.getDeadline();if(deadline!=null){long remaining=Math.min(context.timeoutNanos(),deadline.timeRemaining(TimeUnit.NANOSECONDS));if(remaining<=0)throw Status.DEADLINE_EXCEEDED.asRuntimeException();context=new RequestContext(context.profile(),remaining);}if(backend==null)throw Status.UNIMPLEMENTED.withDescription("Explicit remote mutations require a distributed backend").asRuntimeException();
            call.apply(context).whenComplete((value,failure)->{if(grpc.isCancelled())return;if(failure!=null){observer.onError(ExportWire.serverError(failure));return;}final R response;try{response=RemoteMutationWire.bounded(mapper.apply(java.util.Objects.requireNonNull(value,"Empty mutation backend reply")));}catch(Throwable error){observer.onError(ExportWire.serverError(error));return;}observer.onNext(response);observer.onCompleted();});
        }catch(Throwable failure){observer.onError(ExportWire.serverError(failure));}
    }
    @Override public void owners(RemoteMutationOwnersRequest r,StreamObserver<RemoteMutationOwnersResponse> o){invoke(r,r.hasContext(),r.getContext(),o,c->backend.owners(r.getColumn(),c),v->{if(v.size()>RemoteMutationWire.MAX_ENTRIES)throw new IllegalArgumentException("Too many mutation owners");var b=RemoteMutationOwnersResponse.newBuilder();v.forEach(owner->b.addOwners(RemoteMutationWire.owner(owner)));return b.build();});}
    @Override public void preparePoint(RemoteMutationPreparePointRequest r,StreamObserver<RemoteMutationTokenResponse> o){invoke(r,r.hasContext(),r.getContext(),o,c->{if(!r.hasOwner())throw new IllegalArgumentException("Missing mutation owner");var kind=Mutation.Kind.valueOf(r.getKind());if(kind!=Mutation.Kind.PUT && kind!=Mutation.Kind.DELETE && kind!=Mutation.Kind.MERGE)throw new IllegalArgumentException("Not a point mutation");if(r.getRequestSequence()<0 || r.getEntriesCount()<1 || r.getEntriesCount()>256 || !r.getMulti() && r.getEntriesCount()!=1)throw new IllegalArgumentException("Invalid point identity/count");var owner=RemoteMutationWire.owner(r.getOwner());if(owner.kind()!=RemoteMutationToken.Kind.POINT)throw new IllegalArgumentException("Not a point owner");return backend.preparePoint(owner,DistributedCdcWire.uuid(r.getRequestId()),r.getRequestSequence(),r.getColumn(),RemoteMutationWire.keys(r.getEntriesList()),RemoteMutationWire.values(r.getEntriesList(),r.getValuesPresent()),kind,RequestType.RequestTypeId.valueOf(r.getCallback()),r.getMulti(),c);},v->{var reply=RemoteMutationTokenResponse.newBuilder().setToken(RemoteMutationWire.token(v)).build();RemoteMutationWire.prepared(reply,RemoteMutationWire.owner(r.getOwner()),DistributedCdcWire.uuid(r.getRequestId()),r.getRequestSequence(),RemoteMutationInputs.point(r.getColumn(),Mutation.Kind.valueOf(r.getKind()).ordinal(),RequestType.RequestTypeId.valueOf(r.getCallback()),r.getMulti(),RemoteMutationWire.keys(r.getEntriesList()),RemoteMutationWire.values(r.getEntriesList(),r.getValuesPresent())));return reply;});}
    @Override public void prepareRange(RemoteMutationPrepareRangeRequest r,StreamObserver<RemoteMutationTokenResponse> o){invoke(r,r.hasContext(),r.getContext(),o,c->{if(!r.hasOwner() || r.getRequestSequence()<0)throw new IllegalArgumentException("Missing range authority");var owner=RemoteMutationWire.owner(r.getOwner());if(owner.kind()!=RemoteMutationToken.Kind.RANGE)throw new IllegalArgumentException("Not a range owner");return backend.prepareRange(owner,DistributedCdcWire.uuid(r.getRequestId()),r.getRequestSequence(),r.getColumn(),r.hasLower()?RemoteMutationWire.key(r.getLower()):null,r.hasUpper()?RemoteMutationWire.key(r.getUpper()):null,c);},v->{var reply=RemoteMutationTokenResponse.newBuilder().setToken(RemoteMutationWire.token(v)).build();RemoteMutationWire.prepared(reply,RemoteMutationWire.owner(r.getOwner()),DistributedCdcWire.uuid(r.getRequestId()),r.getRequestSequence(),RemoteMutationInputs.range(r.getColumn(),r.hasLower()?RemoteMutationWire.key(r.getLower()):null,r.hasUpper()?RemoteMutationWire.key(r.getUpper()):null));return reply;});}
    @Override public void prepareBulk(RemoteMutationPrepareBulkRequest r,StreamObserver<RemoteMutationTokenResponse> o){invoke(r,r.hasContext(),r.getContext(),o,c->{if(!r.hasOwner() || r.getRequestSequence()<0)throw new IllegalArgumentException("Missing bulk authority");var owner=RemoteMutationWire.owner(r.getOwner());if(owner.kind()!=RemoteMutationToken.Kind.BULK)throw new IllegalArgumentException("Not a bulk owner");return backend.prepareBulk(owner,DistributedCdcWire.uuid(r.getRequestId()),r.getRequestSequence(),r.getColumn(),r.getMerge(),c);},v->{var reply=RemoteMutationTokenResponse.newBuilder().setToken(RemoteMutationWire.token(v)).build();RemoteMutationWire.prepared(reply,RemoteMutationWire.owner(r.getOwner()),DistributedCdcWire.uuid(r.getRequestId()),r.getRequestSequence(),RemoteMutationInputs.bulkHeader(r.getColumn(),r.getMerge()));return reply;});}
    private void tokenCall(RemoteMutationTokenRequest r,StreamObserver<RemoteMutationObservation> o,BiFunction<RemoteMutationToken,RequestContext,CompletableFuture<RemoteMutationStatus>> call){invoke(r,r.hasContext(),r.getContext(),o,c->call.apply(RemoteMutationWire.token(r.getToken()),c),v->{var response=RemoteMutationWire.status(v);RemoteMutationWire.status(response,RemoteMutationWire.token(r.getToken()));return response;});}
    @Override public void execute(RemoteMutationTokenRequest r,StreamObserver<RemoteMutationObservation> o){tokenCall(r,o,(t,c)->backend.execute(t,c));}
    @Override public void resume(RemoteMutationTokenRequest r,StreamObserver<RemoteMutationObservation> o){tokenCall(r,o,(t,c)->backend.resume(t,c));}
    @Override public void status(RemoteMutationTokenRequest r,StreamObserver<RemoteMutationObservation> o){tokenCall(r,o,(t,c)->backend.status(t,c));}
    @Override public void finishInput(RemoteMutationTokenRequest r,StreamObserver<RemoteMutationObservation> o){tokenCall(r,o,(t,c)->backend.finishInput(t,c));}
    @Override public void results(RemoteMutationResultsRequest r,StreamObserver<RemoteMutationPage> o){invoke(r,r.hasContext(),r.getContext(),o,c->{RemoteMutationWire.budget(r.getOffset(),r.getMaximumItems(),r.getMaximumBytes());return backend.results(RemoteMutationWire.token(r.getToken()),r.getOffset(),r.getMaximumItems(),r.getMaximumBytes(),c);},v->RemoteMutationWire.page(v,r.getOffset(),r.getMaximumItems(),r.getMaximumBytes(),RemoteMutationWire.token(r.getToken())));}
    @Override public void acknowledge(RemoteMutationAcknowledgeRequest r,StreamObserver<RemoteMutationObservation> o){invoke(r,r.hasContext(),r.getContext(),o,c->backend.acknowledge(RemoteMutationWire.token(r.getToken()),RemoteMutationWire.digest(r.getResultDigest()),c),v->{var response=RemoteMutationWire.status(v);RemoteMutationWire.status(response,RemoteMutationWire.token(r.getToken()));return response;});}
    @Override public void appendBatch(RemoteMutationAppendRequest r,StreamObserver<RemoteMutationObservation> o){invoke(r,r.hasContext(),r.getContext(),o,c->{if(r.getOrdinal()<0)throw new IllegalArgumentException("Negative batch ordinal");var token=RemoteMutationWire.token(r.getToken());if(token.kind()!=RemoteMutationToken.Kind.BULK)throw new IllegalArgumentException("Not a bulk token");return backend.appendBatch(token,r.getOrdinal(),new KVBatch.KVBatchRef(RemoteMutationWire.keys(r.getEntriesList()),RemoteMutationWire.values(r.getEntriesList(),true)),RemoteMutationWire.digest(r.getInputDigest()),c);},v->{var response=RemoteMutationWire.status(v);RemoteMutationWire.status(response,RemoteMutationWire.token(r.getToken()));return response;});}
}
